    76  static void
    77  hb_ot_get_glyph_h_advances (hb_font_t* font, void* font_data,
    78                              unsigned count,
    79                              hb_codepoint_t *first_glyph,
    80                              unsigned glyph_stride,
    81                              hb_position_t *first_advance,
    82                              unsigned advance_stride,
    83                              void *user_data HB_UNUSED)
    84  {
    85    const hb_ot_face_data_t *ot_face = (const hb_ot_face_data_t *) font_data;
    86    const OT::hmtx_accelerator_t &hmtx = *ot_face->hmtx.get_relaxed ();
    87
    88    for (unsigned int i = 0; i < count; i++)
    89    {
    90      *first_advance = font->em_scale_x (hmtx.get_advance (*first_glyph, font));
    91      first_glyph = &StructAtOffset<hb_codepoint_t> (first_glyph, glyph_stride);
    92      first_advance = &StructAtOffset<hb_position_t> (first_advance, advance_stride);
    93    }
    94  }
