   137  static hb_bool_t
   138  hb_ot_get_glyph_extents (hb_font_t *font,
   139                           void *font_data,
   140                           hb_codepoint_t glyph,
   141                           hb_glyph_extents_t *extents,
   142                           void *user_data HB_UNUSED)
   143  {
   144    const hb_ot_face_data_t *ot_face = (const hb_ot_face_data_t *) font_data;
   145    bool ret = ot_face->glyf->get_extents (glyph, extents);
   146    if (!ret)
   147      ret = ot_face->CBDT->get_extents (glyph, extents);
   148    // TODO Hook up side-bearings variations.
   149    extents->x_bearing = font->em_scale_x (extents->x_bearing);
   150    extents->y_bearing = font->em_scale_y (extents->y_bearing);
   151    extents->width     = font->em_scale_x (extents->width);
   152    extents->height    = font->em_scale_y (extents->height);
   153    return ret;
   154  }
